// CallingPostTelephonyConfigVirtualExtensions is "Create a Virtual Extension": POST /telephony/config/virtualExtensions.
var CallingPostTelephonyConfigVirtualExtensions = &Operation{
	ID: "CallingPostTelephonyConfigVirtualExtensions", Area: "calling", Group: "virtual-extensions", Command: "create",
	Summary:     "Create a Virtual Extension",
	Description: "Create new Virtual Extension for the given organization or location.\n\nYou can set up virtual extensions at the organization or location level. The organization level enables everyone across your organization to dial the same extension number to reach someone.\nYou can use the location level virtual extension like any other extension assigned to the specific location.\nUsers at the specific location can dial the extension. However, users at other locations can reach the virtual extension by dialing the ESN.\n\nCreating a virtual extension requires a full administrator or location administrator auth token with a scope of `spark-admin:telephony_config_write` and `identity:contacts_rw`.",
	Method:      "POST", Host: HostWebex, Path: "/telephony/config/virtualExtensions",
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Unique identifier for the organization."},
	},
	Body: &Body{Fields: []BodyField{
		{Name: "displayName", Flag: "display-name", Type: "string"},
		{Name: "phoneNumber", Flag: "phone-number", Type: "string"},
		{Name: "extension", Flag: "extension", Type: "string"},
		{Name: "firstName", Flag: "first-name", Type: "string"},
		{Name: "lastName", Flag: "last-name", Type: "string"},
		{Name: "locationId", Flag: "location-id", Type: "string"},
	}},
}

// CallingGetTelephonyConfigVirtualExtensions is "Read the List of Virtual Extensions": GET /telephony/config/virtualExtensions.
var CallingGetTelephonyConfigVirtualExtensions = &Operation{
	ID: "CallingGetTelephonyConfigVirtualExtensions", Area: "calling", Group: "virtual-extensions", Command: "list",
	Summary:     "Read the List of Virtual Extensions",
	Description: "Retrieve virtual extensions associated with a specific customer.\n\nThe GET Virtual Extensions API allows administrators to retrieve a list of virtual extensions configured within their organization. Virtual extensions enable users to dial extension numbers that route to external phone numbers, such as those of remote workers or frequently contacted clients.\nThis API returns key information including the  extension, associated  phone number (in E.164 format), display name, and the location to which the virtual extension belongs\nThe API supports filtering by various parameters, such as extension number, phone number, and location name. The results can be paginated using the `max` and `start` parameters, and the order of the results can be specified using the `order` parameter.\n\nRetrieving a Virtual Extension requires a full or read-only administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Host: HostWebex, Path: "/telephony/config/virtualExtensions",
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Unique identifier for the organization."},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Limit the number of virtual extensions returned to this maximum count. Default is 10."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Start at the zero-based offset in the list of matching virtual extensions. Default is 0."},
		{Name: "order", In: InQuery, Flag: "order", Usage: "Order the list of virtual extensions in ascending or descending order. Default is ascending."},
		{Name: "extension", In: InQuery, Flag: "extension", Usage: "Filter the list of virtual extensions by extension number."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Filter the list of virtual extensions by phone number."},
		{Name: "name", In: InQuery, Flag: "name", Usage: "Filter the list of virtual extensions by name. This can be either first name or last name."},
		{Name: "locationName", In: InQuery, Flag: "location-name", Usage: "Filter the list of virtual extensions by location name.(Only one of the locationName, locationId, and OrgLevelOnly query parameters is allowed at the same time.)"},
		{Name: "locationId", In: InQuery, Flag: "location-id", Usage: "Filter the list of virtual extensions by location ID."},
		{Name: "orgLevelOnly", In: InQuery, Flag: "org-level-only", Usage: "Filter the list of virtual extensions by organization level. If orgLevelOnly is true, return only the organization level virtual extensions."},
	},
	Paging: &webexapi.Paging{Mode: webexapi.Link, Start: "start", Size: "max", Items: "virtualExtensions", OmitEmpty: true},
}

