// CallingPostTelephonyConfigLocationsByLocationIdNumbers is "Add Phone Numbers to a location": POST /telephony/config/locations/{locationId}/numbers.
var CallingPostTelephonyConfigLocationsByLocationIdNumbers = &Operation{
	ID: "CallingPostTelephonyConfigLocationsByLocationIdNumbers", Area: "calling", Group: "numbers", Command: "create-phone-location",
	Summary:     "Add Phone Numbers to a location",
	Description: "Adds a specified set of phone numbers to a location for an organization. Phone numbers must follow the E.164 format.\n\nEach location has a set of phone numbers that can be assigned to people, workspaces, or features. Active phone numbers are in service.\n\nAdding a phone number to a location requires a full administrator auth token with a scope of `spark-admin:telephony_config_write`.\n\nPhone numbers included in the request that already exist in the location will simply be ignored.\n\n<br/>\n\n<div><Callout type=\"warning\">This API is only supported for adding DID and Toll-free numbers to non-integrated PSTN connection types such as Local Gateway (LGW) and Non-integrated CPP. It should never be used for locations with integrated PSTN connection types like Cisco Calling Plans or Integrated CCP because backend data issues may occur.\n</Callout></div>\n<div><Callout type=\"warning\">Mobile numbers can be added to any location that has PSTN connection setup. Only 20 mobile numbers can be added per request.\n</Callout></div>",
	Method:      "POST", Host: HostWebex, Path: "/telephony/config/locations/{locationId}/numbers",
	Params: []Param{
		{Name: "locationId", In: InPath, Flag: "location-id", Required: true, Usage: "LocationId to which numbers should be added."},
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Organization of the Route Group."},
	},
	Body: &Body{Fields: []BodyField{
		{Name: "phoneNumbers", Flag: "phone-numbers", Type: "[]string"},
		{Name: "numberType", Flag: "number-type", Type: "string"},
		{Name: "numberUsageType", Flag: "number-usage-type", Type: "string"},
		{Name: "state", Flag: "state", Type: "string"},
		{Name: "subscriptionId", Flag: "subscription-id", Type: "string"},
		{Name: "carrierId", Flag: "carrier-id", Type: "string"},
	}},
}

