// CallingGetTelephonyConfigJobsNumbersManageNumbersByJobIdErrors is "List Manage Numbers Job errors": GET /telephony/config/jobs/numbers/manageNumbers/{jobId}/errors.
var CallingGetTelephonyConfigJobsNumbersManageNumbersByJobIdErrors = &Operation{
	ID: "CallingGetTelephonyConfigJobsNumbersManageNumbersByJobIdErrors", Area: "calling", Group: "numbers", Command: "list-manage-job-errors",
	Summary:     "List Manage Numbers Job errors",
	Description: "Lists all error details of Manage Numbers job. This will not list any errors if `exitCode` is `COMPLETED`. If the status is `COMPLETED_WITH_ERRORS` then this lists the cause of failures.\n\nList of possible Errors:\n\n+ BATCH-1017021 - Failed to move because it is an inactive number.\n\n+ BATCH-1017022 - Failed to move because the source location and target location have different CCP providers.\n\n+ BATCH-1017023 - Failed because it is not an unassigned number.\n\n+ BATCH-1017024 - Failed because it is a main number.\n\n+ BATCH-1017027 - Manage Numbers Move Operation is not supported.\n\n+ BATCH-1017031 - Hydra request is supported only for single number move job.\n\nThis API requires a full or read-only administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Host: HostWebex, Path: "/telephony/config/jobs/numbers/manageNumbers/{jobId}/errors",
	Params: []Param{
		{Name: "jobId", In: InPath, Flag: "job-id", Required: true, Usage: "Retrieve the error details for this `jobId`."},
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "Retrieve list of jobs for this organization."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Specifies the error offset from the first result that you want to fetch."},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Specifies the maximum number of records that you want to fetch."},
	},
	Paging: &webexapi.Paging{Mode: webexapi.Link, Start: "start", Size: "max", Items: "items", OmitEmpty: true},
}

// CallingGetPartnerReports is "List Reports": GET /partner/reports.
var CallingGetPartnerReports = &Operation{
	ID: "CallingGetPartnerReports", Area: "calling", Group: "partner-reports-templates", Command: "list",
	Summary:     "List Reports",
	Description: "Lists all reports previously generated from a given region. Use query parameters to filter the response. The parameters are optional.\n\nTo access this endpoint, you must use an administrator token with `spark-admin:reports_read` and `identity:people_read` scopes.\n\n<div><Callout type=\"info\">CSV reports for Webex suite services are only supported for organizations based in one region per API request. Organizations based in a different region will require a separate request with region specified.</Callout></div>\n\n<div><Callout type=\"info\">When no region is specified, the request defaults to Partner organization's home region.</Callout></div>\n\n<div><Callout type=\"info\">Reports are usually provided in zip format. A content-header application/zip or application/octet-stream does indicate the zip format. There is usually no .zip file extension.</Callout></div>",
	Method:      "GET", Host: HostWebex, Path: "/partner/reports",
	Params: []Param{
		{Name: "service", In: InQuery, Flag: "service", Usage: "List reports which use this service."},
		{Name: "templateId", In: InQuery, Flag: "template-id", Usage: "List reports with this report template ID."},
		{Name: "from", In: InQuery, Flag: "from", Usage: "List reports that were created on or after this date."},
		{Name: "to", In: InQuery, Flag: "to", Usage: "List reports that were created before this date."},
		{Name: "regionId", In: InQuery, Flag: "region-id", Usage: "Data in the report will be from organizations in this region, for example, US, CA, or EU."},
		{Name: "onBehalfOfSubPartnerOrgId", In: InQuery, Flag: "on-behalf-of-sub-partner-org-id", Usage: "The encoded organization ID for the sub partner."},
	},
	Paging:    &webexapi.Paging{Mode: webexapi.Single},
	TimeRange: TimeISO,
}

// CallingPostPartnerReports is "Create a Report": POST /partner/reports.
var CallingPostPartnerReports = &Operation{
	ID: "CallingPostPartnerReports", Area: "calling", Group: "partner-reports-templates", Command: "create",
	Summary:     "Create a Report",
	Description: "Create a new report. A new report can be created using `templateId` available from the _List Report Templates_ API. For each `templateId`, there are a set of validation rules that need to be followed.\n\nThe `templateId` parameter is a number. However, it is a limitation of developer.webex.com platform that it is passed as a string when you try to test the API from here.\n\nTo access this endpoint, you must use an administrator token with `spark-admin:reports_write` and `identity:people_read` scopes.\n\n**Notes**:\n\n<div><Callout type=\"info\">CSV reports for Webex suite services are only created for organizations in the specified region. Organizations based in a different region will require a separate request with region specified.</Callout></div>\n\n<div><Callout type=\"info\">When no region is specified, the request defaults to Partner organization's home region. A request against a region where there are no organizations will return blank CSV files.</Callout></div>",
	Method:      "POST", Host: HostWebex, Path: "/partner/reports",
	Params: []Param{
		{Name: "onBehalfOfSubPartnerOrgId", In: InQuery, Flag: "on-behalf-of-sub-partner-org-id", Usage: "The encoded organization ID for the sub partner."},
	},
	Body: &Body{Fields: []BodyField{
		{Name: "templateId", Flag: "template-id", Type: "int64"},
		{Name: "startDate", Flag: "start-date", Type: "string"},
		{Name: "endDate", Flag: "end-date", Type: "string"},
		{Name: "regionId", Flag: "region-id", Type: "string"},
	}},
}

