var CallingGetTelephonyConfigPeoplePrimaryAvailableNumbers = &Operation{
	ID: "CallingGetTelephonyConfigPeoplePrimaryAvailableNumbers", Area: "calling", Group: "user-call", Command: "get-person-primary-numbers",
	Summary:     "Get Person Primary Available Phone Numbers",
	Description: "List numbers that are available to be assigned as a person's primary phone number.\nBy default, this API returns standard and mobile numbers from all locations that are unassigned. The parameters `licenseType` and `locationId` must align with the person's settings to determine the appropriate number for assignment.\nFailure to provide these parameters may result in the unsuccessful assignment of the returned number.\n\nThe available numbers APIs help identify candidate numbers and their owning entities to simplify the assignment or association of these numbers to members or features.\n\nRetrieving this list requires a full, read-only or location administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Host: HostWebex, Path: "/telephony/config/people/primary/availableNumbers",
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "List numbers for this organization."},
		{Name: "locationId", In: InQuery, Flag: "location-id", Usage: "Return the list of phone numbers for this location within the given organization. The maximum length is 36."},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Limit the number of phone numbers returned to this maximum count. The default is 2000."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Start at the zero-based offset in the list of matching phone numbers. The default is 0."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Filter phone numbers based on the comma-separated list provided in the `phoneNumber` array."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Filter phone numbers based on the comma-separated list provided in the `phoneNumber` array."},
		{Name: "licenseType", In: InQuery, Flag: "license-type", Usage: "Used to search numbers according to the person's `licenseType` to which the number will be assigned."},
	},
	Paging: &webexapi.Paging{Mode: webexapi.Link, Start: "start", Size: "max", Items: "phoneNumbers", OmitEmpty: true},
}

