// CallingGetTelephonyConfigWorkspacesAvailableNumbers is "Get Workspace Available Phone Numbers": GET /telephony/config/workspaces/availableNumbers.
var CallingGetTelephonyConfigWorkspacesAvailableNumbers = &Operation{
	ID: "CallingGetTelephonyConfigWorkspacesAvailableNumbers", Area: "calling", Group: "workspace-call", Command: "get-available-numbers",
	Summary:     "Get Workspace Available Phone Numbers",
	Description: "List standard numbers that are available to be assigned as a workspace's phone number.\nBy default, this API returns numbers from all locations that are unassigned. To select the suitable number for assignment, ensure the workspace's location ID is provided as the `locationId` request parameter.\n\nThe available numbers APIs help identify candidate numbers and their owning entities to simplify the assignment or association of these numbers to members or features.\n\nRetrieving this list requires a full, read-only or location administrator auth token with a scope of `spark-admin:telephony_config_read`.",
	Method:      "GET", Host: HostWebex, Path: "/telephony/config/workspaces/availableNumbers",
	Params: []Param{
		{Name: "orgId", In: InQuery, Flag: "org-id", Usage: "List numbers for this organization."},
		{Name: "locationId", In: InQuery, Flag: "location-id", Usage: "Return the list of phone numbers for this location within the given organization. The maximum length is 36."},
		{Name: "max", In: InQuery, Flag: "max", Usage: "Limit the number of phone numbers returned to this maximum count. The default is 2000."},
		{Name: "start", In: InQuery, Flag: "start", Usage: "Start at the zero-based offset in the list of matching phone numbers. The default is 0."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Filter phone numbers based on the comma-separated list provided in the `phoneNumber` array."},
		{Name: "phoneNumber", In: InQuery, Flag: "phone-number", Usage: "Filter phone numbers based on the comma-separated list provided in the `phoneNumber` array."},
	},
	Paging: &webexapi.Paging{Mode: webexapi.Link, Start: "start", Size: "max", Items: "phoneNumbers", OmitEmpty: true},
}

